lemma provable_CL_verTranslated : (Hilbert.GL α) ⊢! φ → (Hilbert.Cl α) ⊢! φⱽᴾ := by
  intro h;
  induction h using Deduction.inducition_with_necOnly! with
    | hMaxm a =>
      rcases a with (⟨_, _, rfl⟩ | ⟨_, rfl⟩) <;>
      { simp only [VerTranslation]; trivial; };
    | hMdp ih₁ ih₂ =>
      dsimp [VerTranslation] at ih₁ ih₂;
      exact ih₁ ⨀ ih₂;
    | hNec => dsimp [VerTranslation]; exact imp_id!;
    | _ => dsimp [VerTranslation]; trivial;

theorem not_S4_weakerThan_GL : ¬(Hilbert.S4 ℕ) ≤ₛ (Hilbert.GL ℕ) := by
  apply System.not_weakerThan_iff.mpr;
  existsi (Axioms.T (atom 0));
  constructor;
  . exact axiomT!;
  . exact GL.unprovable_AxiomT;

lemma MDP_Aux (h : (□''X) *⊢[(Hilbert.GL ℕ)]! □φ₁ ⋎ □φ₂) : (□''X) *⊢[(Hilbert.GL ℕ)]! □φ₁ ∨ (□''X) *⊢[(Hilbert.GL ℕ)]! □φ₂ := by
  obtain ⟨Δ, sΓ, hΓ⟩ := Context.provable_iff_boxed.mp h;

  have : (Hilbert.GL ℕ) ⊢! ⋀□'Δ ➝ (□φ₁ ⋎ □φ₂) := FiniteContext.provable_iff.mp hΓ;
  have : (Hilbert.GL ℕ) ⊢! □⋀Δ ➝ (□φ₁ ⋎ □φ₂) := imp_trans''! (by simp) this;
  generalize e : ⋀Δ = c at this;

  have : ((Hilbert.GL ℕ) ⊢! ⊡c ➝ φ₁) ⋎ ((Hilbert.GL ℕ) ⊢! ⊡c ➝ φ₂) := by
    by_contra hC;
    have ⟨h₁, h₂⟩ : ((Hilbert.GL ℕ) ⊬ ⊡c ➝ φ₁) ∧ ((Hilbert.GL ℕ) ⊬ ⊡c ➝ φ₂) := not_or.mp hC;

    obtain ⟨M₁, hM₁⟩ := Hilbert.GL.Kripke.unprovable_iff_exists_unsatisfies_at_root_on_FiniteTransitiveTree.mp h₁;
    obtain ⟨M₂, hM₂⟩ := Hilbert.GL.Kripke.unprovable_iff_exists_unsatisfies_at_root_on_FiniteTransitiveTree.mp h₂;

    replace hM₁ := @Kripke.MDPCounterexampleModel.modal_equivalence_original_world₁ (M₁ := M₁) (M₂ := M₂) M₁.root (⊡c ⋏ ∼φ₁) |>.mp $ Formula.Kripke.Satisfies.not_imp.mp hM₁;
    replace hM₂ := @Kripke.MDPCounterexampleModel.modal_equivalence_original_world₂ (M₁ := M₁) (M₂ := M₂) M₂.root (⊡c ⋏ ∼φ₂) |>.mp $ Formula.Kripke.Satisfies.not_imp.mp hM₂;

    let M := Kripke.MDPCounterexampleModel M₁ M₂;

    have hc : Satisfies M.toModel M.root (□c) := by
      intro x Rrx;
      rcases Kripke.MDPCounterexampleFrame.through_original_root Rrx with ((rfl | Rrx) | (rfl | Rrx))
      . exact (Satisfies.and_def.mp $ (Satisfies.and_def.mp hM₁).1).1;
      . exact (Satisfies.and_def.mp $ (Satisfies.and_def.mp hM₁).1).2 _ Rrx
      . exact (Satisfies.and_def.mp $ (Satisfies.and_def.mp hM₂).1).1;
      . exact (Satisfies.and_def.mp $ (Satisfies.and_def.mp hM₂).1).2 _ Rrx
    have hp₁ : ¬(Satisfies M.toModel M.root (□φ₁)) := by
      dsimp [Satisfies]; push_neg;
      use .inr (.inl M₁.root);
      constructor;
      . apply M.root_rooted; simp;
      . exact (Satisfies.and_def.mp hM₁).2;
    have hp₂ : ¬(Satisfies M.toModel M.root (□φ₂)) := by
      dsimp [Satisfies]; push_neg;
      use .inr (.inr M₂.root);
      constructor;
      . apply M.root_rooted; simp;
      . exact (Satisfies.and_def.mp hM₂).2;
    have : ¬(Satisfies M.toModel M.root (□φ₁ ⋎ □φ₂)) := by
      apply Satisfies.not_def.mpr;
      apply Satisfies.or_def.not.mpr;
      push_neg;
      exact ⟨hp₁, hp₂⟩;
    have : ¬(Satisfies M.toModel M.root (□c ➝ (□φ₁ ⋎ □φ₂))) := _root_.not_imp.mpr ⟨hc, this⟩;
    have := Hilbert.GL.Kripke.unprovable_iff_exists_unsatisfies_at_root_on_FiniteTransitiveTree.mpr ⟨M, this⟩;
    contradiction;

  rcases this with (h | h) <;> {
    subst e;
    have := imply_box_box_of_imply_boxdot_plain! h;
    have := imp_trans''! collect_box_conj! this;
    have := FiniteContext.provable_iff.mpr this;
    have := Context.provable_iff.mpr $ by use □'Δ;
    tauto;
  };

theorem modal_disjunctive (h : (Hilbert.GL ℕ) ⊢! □φ₁ ⋎ □φ₂) : (Hilbert.GL ℕ) ⊢! φ₁ ∨ (Hilbert.GL ℕ) ⊢! φ₂ := by
  have : ∅ *⊢[Hilbert.GL ℕ]! □φ₁ ∨ ∅ *⊢[Hilbert.GL ℕ]! □φ₂ := by simpa using MDP_Aux (X := ∅) (φ₁ := φ₁) (φ₂ := φ₂) $ Context.of! h;
  rcases this with (h | h) <;> {
    have := unnec! $ Context.emptyPrf! h;
    tauto;
  }

lemma unprovable_AxiomL : Hilbert.K4 ℕ ⊬ (Axioms.L (.atom a)) := by
  apply not_imp_not.mpr provable_Cl_trivTranslated;
  apply IntProp.Hilbert.Cl.unprovable_of_exists_classicalValuation;
  use (λ _ => False);
  simp [Axioms.L, TrivTranslation, toPropFormula, IntProp.Formula.Kripke.Satisfies];

lemma unprovable_AxiomP : (Hilbert.Ver ℕ) ⊬ Axioms.P := by
  apply Hilbert.Ver.classical_reducible.not.mpr;
  apply IntProp.Hilbert.Cl.unprovable_of_exists_classicalValuation;
  dsimp [VerTranslation, toPropFormula, IntProp.Formula.Kripke.Satisfies];
  use (λ _ => True);
  simp;

